CREATE TABLE `billingRecords` (
  `id` int AUTO_INCREMENT NOT NULL,
  `userId` int NOT NULL,
  `cloudInstanceId` int,
  `gpuInstanceId` int,
  `instanceType` enum('cloud','gpu') NOT NULL,
  `periodStart` timestamp NOT NULL,
  `periodEnd` timestamp NOT NULL,
  `minutesBilled` decimal(8,2) NOT NULL,
  `pricePerMinute` decimal(12,6) NOT NULL,
  `amount` decimal(12,4) NOT NULL,
  `description` varchar(255),
  `createdAt` timestamp NOT NULL DEFAULT (now()),
  CONSTRAINT `billingRecords_id` PRIMARY KEY(`id`)
);

ALTER TABLE `users` MODIFY COLUMN `accountBalance` decimal(12,4) DEFAULT '0';

ALTER TABLE `cloudInstances` ADD `pricePerMinute` decimal(12,6) DEFAULT '0' NOT NULL;
ALTER TABLE `cloudInstances` ADD `totalBilled` decimal(12,4) DEFAULT '0' NOT NULL;
ALTER TABLE `cloudInstances` ADD `billingStartedAt` timestamp NULL;
ALTER TABLE `cloudInstances` ADD `lastBilledAt` timestamp NULL;

ALTER TABLE `cloudServers` ADD `pricePerMinute` decimal(12,6) DEFAULT '0' NOT NULL;

ALTER TABLE `gpuInstances` ADD `pricePerMinute` decimal(12,6) DEFAULT '0' NOT NULL;
ALTER TABLE `gpuInstances` ADD `totalBilled` decimal(12,4) DEFAULT '0' NOT NULL;
ALTER TABLE `gpuInstances` ADD `billingStartedAt` timestamp NULL;
ALTER TABLE `gpuInstances` ADD `lastBilledAt` timestamp NULL;

ALTER TABLE `gpus` ADD `pricePerMinute` decimal(12,6) DEFAULT '0' NOT NULL;

UPDATE `cloudServers` SET `pricePerMinute` = ROUND(`pricePerHour` / 60, 6);
UPDATE `gpus` SET `pricePerMinute` = ROUND(`pricePerHour` / 60, 6);

